import json
from pathlib import Path

sources = json.loads(Path('source.json').read_text())
drafts = {}


def add(number, xml, reason, notes, **extra):
    assert number not in drafts
    drafts[number] = dict(proposed_xml=xml.strip(), reason=reason, review_notes=notes,
                          status='rewrite_draft', **extra)


add('111 quater J', '''
<p>La redevance sanitaire d'abattage prévue à l'article 302 bis N du code général des impôts est modulée selon le classement des établissements ou, le cas échéant, de leurs chaînes d'abattage. Ce classement tient compte de la fréquence des contrôles officiels à réaliser, au sens du 1 de l'article 3 du règlement (CE) n° 882/2004 du Parlement européen et du Conseil du 29 avril 2004 relatif aux contrôles officiels effectués pour s'assurer de la conformité avec la législation sur les aliments pour animaux et les denrées alimentaires et avec les dispositions relatives à la santé animale et au bien-être des animaux.</p>
<p>Pour les abattages réalisés dans les établissements ou sur les chaînes d'abattage classés, au 31 décembre de l'année précédente, en application de l'article D. 233-15 du code rural et de la pêche maritime, la redevance est réduite pour les catégories A ou B et majorée pour les catégories D ou E.</p>
<p>Pour les abattages ou traitements réalisés dans les établissements ou sur les chaînes d'abattage classés, au 31 décembre de l'année précédente, en application des articles D. 233-16 ou D. 233-17 du même code, la redevance est réduite pour les catégories A ou B et majorée pour les catégories C ou D.</p>
<p>Un arrêté conjoint des ministres chargés de l'agriculture et du budget fixe le taux de modulation de la redevance.</p>
''',
    "Réécriture à droit constant : les deux séries de catégories sont présentées séparément et chaque conséquence tarifaire est explicite. La modulation liée aux contrôles sanitaires est maintenue : sa suppression isolée retirerait aussi les réductions accordées aux établissements les mieux classés et affecterait le financement des contrôles, sans justification établie dans le lot.",
    "Contrôler la coordination du règlement (CE) n° 882/2004 cité par la source avec le règlement (UE) 2017/625, notamment ses dispositions relatives aux redevances des contrôles officiels. Le renvoi ancien est conservé et non présenté comme vérifié au droit actuel. Vérifier hors corpus fourni les catégories des articles D. 233-15 à D. 233-17 et coordonner l'arrêté tarifaire ainsi que les articles 302 bis N à 302 bis R du CGI. Les dates du 31 décembre et les catégories A/B, D/E puis C/D sont conservées ; aucun taux nouveau n'est créé.")

add('111 quater L', '''
<p>Le service des impôts perçoit la redevance sanitaire de découpage auprès des personnes redevables de la redevance sanitaire d'abattage, selon les modalités prévues à l'article 111 quater G.</p>
<p>La redevance est assise sur le poids net de viande fraîche défini à l'article 111 quater LA. Ce poids est constaté lors de la pesée, puis réduit des abattements prévus au même article.</p>
<p>Pour la seule redevance sanitaire de découpage, la déclaration d'existence prévue au 1° de l'article 111 quater G n'est pas exigée lorsque les informations nécessaires à l'identification de l'établissement et de l'exploitant ont déjà été communiquées à l'administration dans le cadre de l'agrément sanitaire ou de la redevance sanitaire d'abattage. Les services concernés se transmettent ces informations dans le respect des secrets protégés par la loi.</p>
<p>Pour cette même redevance, le redevable n'adresse pas au service chargé de l'agriculture une seconde copie des éléments déclarés au service des impôts en application de l'article 111 quater G. Le service des impôts assure cette transmission.</p>
<p>Les dispenses prévues aux troisième et quatrième alinéas s'appliquent aux formalités à accomplir à compter de l'entrée en vigueur de la présente réforme. Elles ne modifient ni l'assiette de la redevance ni les obligations de paiement et de justification des opérations.</p>
''',
    "Droit constant pour le redevable, le recouvrement et l'assiette. Réforme de fond : suppression, pour la redevance de découpage, de la déclaration d'existence déjà satisfaite par une identification administrative et de l'envoi par le redevable d'un second relevé identique au service agricole. La transmission est effectuée entre services ; le paiement et les preuves restent exigibles.",
    "Coordonner expressément les 1° et 3° de l'article 111 quater G de l'annexe III, lu dans le corpus, sans étendre ces dispenses à la redevance d'abattage hors de leur champ. Le double envoi figure dans l'alinéa suivant le premier alinéa du 3° de cet article. Organiser l'échange légal entre services fiscaux et sanitaires, ses habilitations et ses données strictement nécessaires. Les exigences européennes de contrôle et de financement restent maintenues ; aucun nouveau fichier déclaratif à la charge du redevable n'est prévu.")

add('111 quater LA', '''
<p>I. - Pour les animaux des espèces bovine, ovine, caprine, chevaline et asine, pour les croisements des espèces chevaline et asine ainsi que pour les gibiers ongulés d'élevage ou sauvages, le poids net de viande correspond au poids des quatre quartiers de l'animal abattu, saigné, dépouillé et éviscéré, après déduction des éléments suivants :</p>
<p>a) La tête, enlevée par section à l'articulation de l'occiput et de la première vertèbre cervicale, suivant un plan perpendiculaire au grand axe des vertèbres cervicales ;</p>
<p>b) La partie des membres située au-delà de la section pratiquée à l'articulation du genou pour les membres antérieurs et à celle du jarret pour les membres postérieurs ;</p>
<p>c) Les organes contenus dans les cavités thoracique, abdominale et pelvienne, à l'exception des rognons et des graisses de rognons pour les veaux et les ovins ;</p>
<p>d) Les organes génitaux et mammaires ;</p>
<p>e) Pour les gros bovins, les produits du parage des gouttières jugulaires, dans la limite d'un kilogramme par animal, et les graisses externes des régions dorsales et latérales. L'enlèvement de ces graisses ne doit pas mettre à nu le tissu musculaire.</p>
<p>II. - Pour les animaux de l'espèce porcine, le poids net de viande correspond au poids de l'animal abattu, saigné et éviscéré, présenté en carcasse entière ou divisée par le milieu. Il comprend la tête et les pieds, mais exclut les soies, les sabots, les organes génitaux, la langue, la panne, les rognons et le diaphragme.</p>
<p>La carcasse de porc peut toutefois être présentée à la pesée avec la langue. Dans ce cas, le poids net de viande constaté à chaud est réduit de 0,5 %, en plus de l'abattement prévu au V.</p>
<p>III. - Les volailles comprennent les coqs, poules, poulets, canards, oies, dindes et pintades ainsi que les autres oiseaux élevés et abattus comme des animaux domestiques.</p>
<p>Pour les volailles, les lapins domestiques et les gibiers d'élevage ou sauvages autres qu'ongulés, le poids net de viande à retenir est celui de la carcasse, découpée ou non.</p>
<p>IV. - Toute partie de l'animal qui reste attenante à la carcasse au moment de la pesée entre dans le poids net de viande.</p>
<p>V. - Pour les animaux de boucherie et de charcuterie, la pesée est effectuée dans l'heure suivant l'étourdissement. Le poids net de viande constaté est réduit de 2,5 % pour les viandes d'animaux de l'espèce porcine et de 2 % pour les viandes d'animaux des espèces bovine, ovine, caprine, chevaline et asine ainsi que des croisements des espèces chevaline et asine.</p>
<p>Pour les volailles, les lapins domestiques et les gibiers d'élevage ou sauvages, la pesée est effectuée dans les vingt-quatre heures suivant l'abattage ou, pour le gibier sauvage, le traitement. Elle porte sur chacun des lots d'animaux abattus ou traités par un même propriétaire ou pour son compte.</p>
<p>Les quantités nettes de viande portées sur la déclaration prévue à l'article 111 quater G sont arrondies au kilogramme le plus proche. Elles bénéficient des abattements suivants, eux-mêmes arrondis au kilogramme le plus proche :</p>
<p>10 % du poids net de viande pour les animaux de l'espèce porcine, afin de tenir compte de la tête et des pieds pesés avec la carcasse ;</p>
<p>5 % du poids net de viande pour les volailles dont le foie et le gésier ont été détachés de la carcasse, mais pesés et emballés avec celle-ci.</p>
''',
    "Réécriture à droit constant : les éléments inclus ou retirés de la pesée, les espèces et les abattements sont explicités sans modifier l'assiette. Les délais et les abattements sont maintenus, car retirer isolément ces définitions créerait une assiette indéterminée ou ferait perdre des réductions aux redevables, plutôt que supprimer une charge inutile.",
    "Contrôle ciblé : limite de 1 kilogramme pour le parage ; abattement additionnel de 0,5 % avec langue ; 2,5 % pour les porcs et 2 % pour les autres espèces désignées ; abattements de 10 % et 5 % ; pesées dans l'heure et dans les vingt-quatre heures ; arrondis au kilogramme. Les déductions particulières des rognons et graisses de rognons demeurent exclues pour veaux et ovins. Conserver la distinction entre IV (éléments attenants) et II/III (présentations particulières). Renvois à 111 quater G et 111 quater L maintenus.")

add('111 quater M', '''
<p>Pour les carcasses de volailles, de lapins domestiques ou de gibiers d'élevage ou sauvages autres qu'ongulés, la redevance sanitaire de découpage n'est pas due lorsque leur destination est autre qu'un atelier de découpe agréé en application de l'article L. 233-2 du code rural et de la pêche maritime. L'abatteur, le tiers abatteur, la personne qui traite le gibier sauvage, celle qui réalise des acquisitions intracommunautaires, l'importateur ou le déclarant en douane doit justifier de cette destination.</p>
<p>Pour les opérations réalisées à compter de l'entrée en vigueur de la présente réforme, cette justification peut résulter des documents commerciaux ou de transport déjà établis pour l'opération. Aucun certificat distinct n'est exigé au titre du présent article lorsque ces documents établissent la destination des carcasses.</p>
''',
    "Droit constant pour les espèces concernées, les personnes admises à justifier la destination et la condition d'exonération. Réforme de fond : les documents commerciaux ou de transport probants suffisent expressément ; une attestation supplémentaire ne peut être exigée pour la même information.",
    "La source ne fixe pas de forme exclusive de preuve : la dispense nouvelle ferme la possibilité d'une demande systématique de certificat, sans supprimer la preuve ni les contrôles de destination. Coordonner les pratiques et formulaires de la redevance prévue à l'article 302 bis S du CGI et le renvoi à L. 233-2 du code rural et de la pêche maritime. La règle vise les carcasses et ne s'étend pas à toute viande découpée.")

add('111 quater N', '''
<p>En cas de saisie totale ou partielle pratiquée par les services d'inspection sanitaire dans un abattoir ou un établissement agréé de traitement du gibier sauvage, la redevance sanitaire de découpage n'est pas perçue sur les viandes ou parties de viande saisies. Elle n'est pas non plus perçue sur les viandes achetées par les organismes d'intervention.</p>
''',
    "Réécriture à droit constant : une phrase est consacrée à chacun des deux cas de non-perception, dans le même alinéa. Le maintien de ces exclusions évite de taxer les viandes saisies ou retirées du circuit ordinaire ; leur abrogation augmenterait le prélèvement et ne supprimerait aucune formalité propre à cet article.",
    "Conserver les saisies partielles aussi bien que totales, les deux catégories de lieux et les achats par les organismes d'intervention. Articuler cette exclusion avec l'article 302 bis S du CGI, sans modifier les décisions sanitaires de saisie ni la destination des produits saisis.")

add('111 quater O', '''
<p>La redevance sanitaire de découpage n'est pas due pour les viandes suivantes lorsqu'elles sont exportées ou expédiées vers un autre État membre de la Communauté européenne : les viandes présentées en carcasse, quelle que soit l'espèce ; les viandes des espèces bovine, ovine, caprine, porcine, chevaline et asine, celles issues des croisements des espèces chevaline et asine ainsi que les viandes de gibiers ongulés d'élevage ou sauvages, lorsqu'elles sont présentées en carcasse, demi-carcasse, demi-carcasse découpée en trois morceaux de gros au maximum ou quartiers.</p>
''',
    "Réécriture à droit constant : l'exonération commune est placée en tête et les présentations admises sont distinguées. Le chevauchement entre les deux groupes de carcasses est conservé pour ne pas restreindre une exonération. Aucun prélèvement ni justificatif nouveau n'est ajouté.",
    "La source comporte déjà une répétition entre carcasses de toutes espèces et carcasses des espèces énumérées. Autre décalage préexistant : l'article 302 bis S du CGI lu dans le corpus formule l'exclusion avec les livraisons des articles 262 ter et 258 A et une justification de l'exportation, de l'expédition ou du transport. Ne pas interpréter la rédaction de l'annexe comme supprimant ces conditions législatives ; harmoniser les deux textes lors de la coordination d'ensemble. Le maximum de trois morceaux, les quartiers et la distinction exportation/expédition sont conservés.")

# Les deux tableaux sont repris cellule par cellule, sans attribut de présentation.
import xml.etree.ElementTree as ET


def source_table(index):
    root = ET.fromstring('<div>' + sources[index]['source_xml'] + '</div>')
    tables = root.findall('.//table')
    assert len(tables) == 1
    table = tables[0]
    for element in table.iter():
        for key in list(element.attrib):
            if key not in ('rowspan', 'colspan'):
                del element.attrib[key]
    return ET.tostring(table, encoding='unicode')


add('111 quater P', '''
<p>À l'importation, la redevance sanitaire de découpage est perçue, selon les modalités prévues à l'article 111 quater R, sur les viandes énumérées dans le tableau suivant lorsqu'elles sont déclarées pour la mise à la consommation sur le territoire douanier.</p>
''' + source_table(6) + '''
<p>Pour les préparations et conserves relevant des numéros ex 1601 et ex 1602 du tarif des douanes qui contiennent des viandes de plusieurs espèces, le tarif applicable est le plus faible des tarifs prévus pour les viandes entrant dans leur composition. Cette règle s'applique aux viandes de boucherie, de charcuterie, de volailles, de lapins domestiques et de gibiers d'élevage ou sauvages.</p>
''',
    "Réécriture à droit constant : le fait générateur à l'importation et le choix du tarif le plus faible pour les mélanges sont formulés directement. Le tableau entier est conservé, car il délimite l'assiette par marchandise et ne constitue pas une formalité autonome supprimable. Ses libellés techniques sont volontairement maintenus ; la proposition ne se limite pas à leur copie.",
    "Tableau contrôlé : treize lignes de marchandises, en plus de l'en-tête ; préfixes Ex, références 0201 à 1902.20.30, renvois 0101 à 0105 et seuil de plus de 20 % maintenus. Les attributs de mise en page de la source sont supprimés pour respecter le schéma XML autorisé. Vérifier la correspondance des anciennes positions avec la nomenclature douanière applicable et le financement européen des contrôles officiels avant toute modification tarifaire. Le tarif minimal des mélanges vise ex 1601 et ex 1602, non l'ensemble du tableau.")

add('111 quater Q', '''
<p>Pour les viandes provenant d'un autre État membre de la Communauté européenne, la redevance sanitaire de découpage est perçue selon les modalités prévues à l'article 111 quater R lorsque les viandes remplissent les conditions suivantes : elles proviennent d'animaux des espèces bovine, ovine, caprine, porcine, chevaline ou asine, des croisements des espèces chevaline et asine, ou de gibiers ongulés d'élevage ou sauvages ; elles sont présentées en carcasse, demi-carcasse, demi-carcasse découpée en trois morceaux de gros au maximum ou quartiers ; elles relèvent des rubriques du tableau suivant.</p>
''' + source_table(7),
    "Réécriture à droit constant : l'origine, les espèces, la présentation et le classement tarifaire sont exposés comme des conditions cumulatives. Les six lignes du tableau sont maintenues intégralement. La suppression isolée de ce régime, alors que les viandes nationales restent taxées, ne serait pas une simplification coordonnée de la redevance sanitaire.",
    "Conserver les six rubriques Ex 0201, Ex 0202, Ex 0203, Ex 0204, Ex 0205-00-00 et 0208, leurs désignations et le maximum de trois morceaux. Les attributs de présentation sont retirés. Coordonner avec l'acquisition intracommunautaire visée au dernier alinéa de 302 bis S du CGI et avec 111 quater O et R. Contrôler les références douanières anciennes et les règles européennes de financement des contrôles sans assimiler acquisition intracommunautaire et importation de pays tiers.")

add('111 quater R', '''
<p>La redevance prévue aux articles 111 quater P et 111 quater Q est calculée sur le poids net de viande, après déduction du poids des abats. Ce poids est arrondi au kilogramme le plus proche.</p>
<p>Pour les volailles dont le foie et le gésier ont été détachés de la carcasse, mais pesés et emballés avec celle-ci, le poids retenu bénéficie en outre d'un abattement de 5 %, également arrondi au kilogramme le plus proche.</p>
''',
    "Réécriture à droit constant : le calcul du poids imposable et l'abattement pour les volailles sont énoncés dans l'ordre de calcul. L'abattement est maintenu comme une réduction de charge ; sa suppression augmenterait la redevance sans retirer de déclaration distincte.",
    "Les renvois à 111 quater P et Q, l'exclusion des abats, le taux de 5 % et les deux arrondis sont conservés. Ne pas appliquer ici les autres abattements de 111 quater LA, qui relève d'un champ distinct. La présence conjointe du foie et du gésier détachés, pesés et emballés avec la carcasse reste requise.")

add('111 quater U', '''
<p>Le présent article est abrogé à compter de l'entrée en vigueur de la présente réforme.</p>
<p>À compter de cette date, aucune formalité déclarative ou de paiement ne peut être exigée sur le seul fondement du présent article pour la redevance sanitaire relative à l'agrément des établissements du secteur de l'alimentation animale. La déclaration, la liquidation et le paiement prévus à l'article 302 bis WD du code général des impôts demeurent régis par cet article et ne donnent pas lieu à une seconde déclaration au titre du présent article.</p>
<p>Les obligations régulièrement nées avant cette date, leur contrôle, leur recouvrement, les restitutions, les contentieux et les délais de prescription demeurent régis par les dispositions antérieurement applicables. La présente abrogation n'ouvre aucun droit à un remboursement général des sommes régulièrement acquittées.</p>
''',
    "Abrogation de fond d'un doublon réglementaire : l'article 302 bis WD du CGI, lu intégralement dans le corpus, fixe déjà la déclaration sur l'annexe de TVA de mars ou du premier trimestre, la déclaration annuelle du régime simplifié et le paiement au dépôt. Le texte interdit une formalité supplémentaire tirée de cette répétition. La redevance législative et l'agrément sanitaire ne sont pas supprimés ; aucune baisse de prélèvement n'est annoncée.",
    "Coordonner 302 bis WD et les formulaires sans les supprimer : le niveau législatif maintient la charge fiscale et ses échéances. La note historique du décret n° 2014-1687, article 2, vise les périodes postérieures au 1er janvier 2015 ; cette date n'est pas celle de la réforme proposée. La suppression d'une redevance sanitaire elle-même demanderait une modification législative et l'examen des contraintes européennes de financement ; elle n'est pas réalisée par la présente abrogation du doublon.",
    change_type='full_repeal', repeal_policy_id='editorial_direction_2026_10_19',
    repeal_scope="Suppression du fondement réglementaire redondant imposant la déclaration et le paiement de la redevance d'agrément des établissements d'alimentation animale ; maintien des seules obligations législatives de 302 bis WD et des situations antérieures.")

add('111 quinquies', '''
<p>Lorsque le représentant unique prévu à l'article 302 decies du code général des impôts est tenu, en application de l'article 1671 du même code, d'accomplir les obligations d'une personne représentée, il accomplit l'ensemble des obligations de cette personne auprès du service des impôts des entreprises étrangères de la direction des impôts des non-résidents.</p>
''',
    "Réécriture à droit constant : la condition tirée de la retenue à la source et le service compétent sont énoncés directement. Le guichet unique est maintenu, car il évite déjà la dispersion des démarches du représentant. Aucune nouvelle obligation de représentation n'est créée.",
    "Les articles 302 decies et 1671 du CGI ont été lus dans le corpus. La règle ne s'applique que lorsqu'une représentation est exigée au titre de 1671 ; elle ne supprime pas ses exemptions de désignation, notamment selon l'établissement du débiteur et l'assistance au recouvrement. Ne pas étendre la compétence de ce service aux autres représentations sur le seul fondement de l'expression « ensemble des obligations » hors de la condition posée par la source.")

add('111-00 D', '''
<p>Pour les destructions d'alcool et de boissons alcooliques en suspension de droits réalisées à compter de l'entrée en vigueur de la présente réforme, l'entrepositaire agréé adresse une déclaration écrite au service des douanes. Cette déclaration doit lui parvenir au plus tard trois jours ouvrables avant l'opération. Elle tient lieu de la demande préalable ; aucune autorisation préalable distincte n'est exigée au titre du présent article. La déclaration indique la date et l'heure de l'opération, son motif et le lieu de destruction ou d'envoi sur un site de destruction. Elle précise la nature et le volume des produits, par tarif d'imposition et par produit concerné défini aux articles 286 I et 286 J de l'annexe II au code général des impôts. Lorsque l'administration vérifie l'opération, l'exonération des droits d'accise porte sur les produits et volumes qu'elle reconnaît. En l'absence de réponse de l'administration ou si le service n'est pas présent lors de la destruction ou de l'envoi sur le site de destruction, l'exonération porte sur les produits et volumes indiqués dans la déclaration. Cette règle ne dispense pas de la destruction effective des produits et ne fait pas obstacle au contrôle d'une déclaration inexacte ou frauduleuse. L'entrepositaire inscrit les produits détruits en sortie dans sa comptabilité matières.</p>
<p>Les opérations réalisées avant l'entrée en vigueur de la présente réforme restent soumises aux règles antérieurement applicables, y compris pour leur contrôle et les recours.</p>
''',
    "Réforme de fond : la demande préalable est remplacée par une notification sans autorisation distincte. La réécriture distingue les informations à fournir et les effets du contrôle ou de l'absence du service, dans le même alinéa que la source. Le délai de trois jours ouvrables, la comptabilité matières et la preuve d'une destruction réelle préservent le contrôle antifraude. La source accordait déjà l'exonération en cas de silence ou d'absence ; cet acquis est conservé.",
    "Conserver les deux cas alternatifs, absence de réponse OU absence du service, y compris lors de l'envoi vers le site, et les références 286 I et 286 J de l'annexe II. Coordonner les formulaires douaniers et les règles européennes d'exonération pour destruction en suspension d'accise, notamment la directive (UE) 2020/262 ; la déclaration et la faculté de contrôle restent effectives. Ne pas appliquer cette simplification au régime distinct de destruction des tabacs sur le fondement du seul présent article. Aucune exigence de délai tirée d'une note historique n'est créée.")

add('111-0 A', '''
<p>Sans préjudice de l'article 502 du code général des impôts, les niveaux mentionnés au 3° du I de l'article 302 G du même code ne peuvent être inférieurs aux quantités suivantes :</p>
<p>a) 10 litres pour les alcools et les boissons spiritueuses ;</p>
<p>b) 20 litres pour les produits intermédiaires ;</p>
<p>c) 90 litres pour les vins et autres produits fermentés, dont 60 litres pour les vins mousseux ;</p>
<p>d) 60 litres pour les vins mousseux ;</p>
<p>e) 110 litres pour les bières.</p>
''',
    "Réécriture à droit constant des quantités servant à l'application du statut d'entrepositaire agréé. Les lettres et seuils restent distincts. Les supprimer isolément ferait disparaître le repère de contrôle des ventes commerciales d'alcools ; ce n'est pas une simple formalité en double.",
    "La source répète déjà les 60 litres de vins mousseux aux c et d : répétition signalée, conservée pour ne pas modifier silencieusement le champ. La formule source « niveaux ... égaux ou supérieurs » fixe un minimum pour ces niveaux ; elle n'est pas transformée en règle de dépassement par destinataire. Le 3° du I de 302 G, lu dans le corpus, vise des quantités supérieures aux niveaux et conserve sa portée propre. Le niveau lui-même ne vaut ni franchise pour voyageurs ni présomption automatique d'usage personnel. Renvois anciens à 302 G et 502 à coordonner avec la recodification des accises.")

add('111-0 B', '''
<p>I. - Les entrepositaires agréés mentionnés à l'article 302 G du code général des impôts et les destinataires enregistrés mentionnés à l'article 302 H ter du même code bénéficient de plein droit, respectivement, de la dispense de caution prévue au 2 du III de l'article 302 D et au premier alinéa du I de l'article 302 H ter lorsque les droits d'accise dont ils sont redevables n'excèdent pas 22 881 € par an. Ce montant est relevé au 1er janvier de chaque année selon le taux de croissance de l'indice des prix à la consommation hors tabac de l'avant-dernière année, dans la limite de 1,75 %. Il est arrondi à l'euro le plus proche ; une fraction de 0,50 euro est comptée pour 1 euro.</p>
<p>Le montant annuel correspond à la moyenne annuelle des opérations taxables réalisées au cours des deux dernières années civiles. Pour les entrepositaires agréés qui acquittent les droits en une échéance annuelle unique, cette moyenne est calculée sur les deux dernières années à la date de l'échéance fixée au 4 du III de l'article 302 D du code général des impôts.</p>
<p>Si la durée d'exercice de la profession est comprise entre huit et vingt-trois mois inclus, la moyenne annuelle est calculée sur la période d'activité écoulée à la fin de la dernière année civile. Le montant des opérations taxables arrêté au 31 décembre est ramené à une année. Si la durée d'exercice est inférieure à huit mois, l'opérateur estime le montant des opérations taxables qu'il prévoit de réaliser pendant les douze mois suivant le démarrage de son activité et communique cette estimation à l'administration fiscale. Une estimation préalable par l'administration n'est pas requise ; l'estimation communiquée reste contrôlable.</p>
<p>II. - Les entrepositaires agréés qui détiennent, dans un entrepôt suspensif de droits d'accise, les produits mentionnés au 1° du I de l'article 302 G du code général des impôts bénéficient de plein droit de la dispense de caution prévue au 3° du deuxième alinéa du V de cet article lorsque les droits suspendus n'excèdent pas le montant fixé au premier alinéa du I du présent article. Les droits suspendus sont appréciés à partir du stock mensuel maximal enregistré au cours de la dernière année civile. Le seuil est relevé dans les mêmes conditions que celles prévues au premier alinéa du I.</p>
<p>Si l'entrepositaire ne justifie pas d'une année d'exercice, il estime les droits suspendus à partir du stock mensuel maximal de produits fiscalisés qu'il prévoit de détenir pendant les douze mois suivant le démarrage de son activité et communique cette estimation à l'administration fiscale. Une estimation préalable par l'administration n'est pas requise ; l'estimation communiquée reste contrôlable.</p>
<p>Le bénéfice de plein droit de la dispense et les modalités d'estimation par l'opérateur s'appliquent à compter de l'entrée en vigueur de la présente réforme. Les cautionnements garantissant des droits nés auparavant restent régis, pour ces droits, par les règles antérieures.</p>
''',
    "Réforme de fond : sous les seuils existants, la dispense devient de plein droit et le démarrage d'activité repose sur une estimation déclarée par l'opérateur plutôt que sur une estimation administrative préalable. La reconstitution annuelle, le seuil, son indexation plafonnée, le contrôle et la garantie des droits antérieurs sont maintenus. La rédaction distingue paiement des droits et risque lié aux stocks suspendus.",
    "Coordonner 111-0 C et D, 302 D III, 302 G V et 302 H ter I ; les dispenses ne couvrent pas indistinctement les mouvements intracommunautaires soumis à garantie. Le seuil source de 22 881 € est conservé sans recalcul inventé pour 2026 : vérifier son indexation et la version datée du 1er juillet 2026. La note de conséquence du décret n° 2013-887 (articles 1er-1° et 4) ne suffit pas à expliquer cette date. Points contrôlés : deux années, huit à vingt-trois mois inclus, moins de huit mois, douze mois, 31 décembre, 1er janvier, 0,50 et plafond de 1,75 %. La référence à 302 D est absente du fichier impots.json consulté ; coordonner la recodification sans inventer un numéro de remplacement. Respecter les garanties européennes de recouvrement des accises.")

add('111-0 C', '''
<p>À compter de l'entrée en vigueur de la présente réforme, la dispense prévue à l'article 111-0 B s'applique lorsque ses conditions sont remplies, sans demande ni décision préalable du comptable des douanes. L'administration peut vérifier ces conditions ; toute décision refusant le bénéfice de la dispense est motivée et notifiée à l'entrepositaire agréé ou au destinataire enregistré.</p>
<p>L'entrepositaire agréé ou le destinataire enregistré qui ne remplit plus les conditions de la dispense prévue au I de l'article 111-0 B fournit, dans le mois suivant la fin de l'année en cours, une caution solidaire garantissant le paiement des droits dus, conformément au 2 du III de l'article 302 D et au premier alinéa du I de l'article 302 H ter du code général des impôts.</p>
<p>Pour l'entrepositaire agréé qui acquitte les droits en une échéance annuelle unique, ce délai d'un mois court à compter de l'échéance fixée au 4 du III de l'article 302 D du code général des impôts.</p>
<p>L'entrepositaire agréé qui ne remplit plus les conditions de la dispense prévue au II de l'article 111-0 B fournit, dans le mois suivant le dépassement du seuil, une caution solidaire garantissant le paiement des droits dus, conformément au premier alinéa du V de l'article 302 G du code général des impôts.</p>
<p>Le non-respect des obligations prévues aux deuxième, troisième et quatrième alinéas peut entraîner le retrait de l'agrément prévu au sixième alinéa du V de l'article 302 G et au quatrième alinéa du I de l'article 302 H ter du même code.</p>
<p>Les dispenses déjà accordées demeurent valables sous réserve du maintien de leurs conditions. Les cautionnements garantissant des droits nés avant l'entrée en vigueur de la présente réforme restent régis, pour ces droits, par les règles antérieures.</p>
''',
    "Réforme de fond coordonnée avec 111-0 B : suppression de l'autorisation préalable de dispense, remplacée par le bénéfice de plein droit et un contrôle ultérieur motivé. Les délais de reconstitution d'une caution, les trois déclencheurs distincts et la possibilité de retrait d'agrément sont maintenus contre le risque d'impayé.",
    "Les alinéas 2, 3 et 4 restent à leur place et le renvoi interne du cinquième alinéa reste exact. Maintenir un mois suivant la fin d'année pour le I, un mois suivant l'échéance annuelle spéciale et un mois après dépassement pour les stocks du II. Les renvois au sixième alinéa de 302 G V et au quatrième alinéa de 302 H ter I correspondent aux facultés de retrait dans les sources lues du corpus ; préserver ce comptage lors de leur réécriture. Coordonner le texte succédant à 302 D, absent du fichier consulté, sans inventer son numéro. Les garanties pour droits antérieurs ne sont pas libérées rétroactivement.")

add('111-0 D', '''
<p>I. - La dispense de caution prévue au 2° du deuxième alinéa du V de l'article 302 G du code général des impôts bénéficie aux producteurs de vin qui remplissent cumulativement les deux conditions suivantes, appréciées en moyenne sur trois ans : produire moins de 1 000 hectolitres de vin par an et expédier vers un autre État membre, en suspension de droits, moins de 1 000 hectolitres de vin par an.</p>
<p>La moyenne est calculée sur les trois années d'activité de vin écoulées à la date du dépôt de la déclaration annuelle de récolte prévue à l'article 407 du code général des impôts. Lorsque l'activité a commencé depuis moins de trois ans, elle est calculée sur la période d'activité écoulée, ramenée à une année. Si aucune activité n'a encore été réalisée, le producteur communique à l'administration une estimation annuelle de sa production et de ses expéditions. L'absence de trois années d'activité ne fait pas obstacle à la dispense ; les quantités déclarées restent contrôlables.</p>
<p>II. - Le producteur bénéficiant de cette dispense justifie de la qualité d'entrepositaire agréé prévue au 1° du I de l'article 302 G du code général des impôts. Il reste tenu de payer les droits exigibles en cas de non-apurement des documents d'accompagnement qu'il a souscrits, en application de l'article 302 P du même code.</p>
<p>III. - La dispense s'applique de plein droit lorsque les conditions des I et II sont remplies. Aucune demande ni décision préalable du comptable des douanes n'est exigée. Toute décision refusant le bénéfice de la dispense est motivée et notifiée au producteur.</p>
<p>IV. - Le producteur qui ne remplit plus les conditions du I fournit, dans le mois suivant la date de dépôt de sa dernière déclaration annuelle de récolte, une caution solidaire garantissant le paiement des droits dus, conformément au premier alinéa du V de l'article 302 G du code général des impôts.</p>
<p>Le non-respect de cette obligation peut entraîner le retrait de l'agrément prévu au sixième alinéa du V de l'article 302 G.</p>
<p>V. - Les entrepositaires agréés mentionnés à l'article 302 G du code général des impôts qui expédient sur le territoire national, en suspension de droits d'accise, les produits mentionnés au 1° du I de cet article bénéficient de plein droit de la dispense de caution prévue au 3° du deuxième alinéa du V du même article lorsque les droits suspendus n'excèdent pas le montant fixé au premier alinéa du I de l'article 111-0 B. Ce seuil est relevé dans les conditions prévues au même alinéa.</p>
<p>Le montant annuel correspond à la moyenne annuelle des droits suspendus au titre des expéditions nationales réalisées au cours des deux dernières années civiles.</p>
<p>Si l'entrepositaire exerce sa profession depuis huit à vingt-trois mois inclus, cette moyenne est établie à partir des expéditions nationales en suspension de droits réalisées pendant la période d'activité écoulée à la fin de la dernière année civile. Les droits suspendus arrêtés au 31 décembre sont ramenés à une année. Si la durée d'exercice est inférieure à huit mois, l'entrepositaire estime les droits suspendus au titre des expéditions nationales qu'il prévoit de réaliser pendant les douze mois suivant le démarrage de son activité et communique cette estimation à l'administration fiscale. Une estimation préalable par l'administration n'est pas requise ; l'estimation communiquée reste contrôlable.</p>
<p>VI. - La dispense prévue au V s'applique sans demande ni décision préalable du comptable des douanes. Toute décision refusant son bénéfice est motivée et notifiée à l'entrepositaire.</p>
<p>L'entrepositaire qui ne remplit plus les conditions du V fournit, dans le mois suivant la fin de l'année en cours, une caution solidaire garantissant le paiement des droits dus, conformément au premier alinéa du V de l'article 302 G du code général des impôts.</p>
<p>Le non-respect de cette obligation peut entraîner le retrait de l'agrément prévu au sixième alinéa du V de l'article 302 G.</p>
<p>Les nouvelles modalités d'accès aux dispenses s'appliquent à compter de l'entrée en vigueur de la présente réforme. Les cautionnements garantissant des droits nés auparavant restent régis, pour ces droits, par les règles antérieures. Les dispenses déjà accordées sont conservées sous réserve du maintien de leurs conditions.</p>
''',
    "Réforme de fond : suppression de l'exclusion automatique pendant les trois premières années pour les petits producteurs de vin, accès de plein droit aux dispenses et remplacement de l'estimation administrative au démarrage par une estimation de l'opérateur. La moyenne de trois ans reste la règle pour les activités établies ; les deux plafonds stricts de 1 000 hectolitres, l'agrément, la dette en cas de non-apurement et les délais de reconstitution de caution restent inchangés. Les numéros I à VI et les régimes intracommunautaire et national restent séparés.",
    "Coordonner 302 G V, 302 P, 407 et les articles 111-0 B/C. Vérifier la compatibilité de l'accès des nouveaux producteurs avec les règles européennes de garantie des mouvements en suspension, notamment la directive (UE) 2020/262 et le régime des petits producteurs de vin ; aucune dispense générale des garanties intracommunautaires n'est instituée hors du I. Points conservés : moins de 1 000 hectolitres pour chacun des deux critères, trois ans, deux années civiles, huit à vingt-trois mois, moins de huit mois, douze mois, 31 décembre et délais d'un mois distincts aux IV/VI. Le renvoi au sixième alinéa de 302 G V correspond au retrait d'agrément dans la source lue : préserver ce comptage. Aucun remboursement rétroactif des frais de caution n'est créé.")

add('111-0 E', '''
<p>I. - Pour l'application des I et II de l'article 302 D bis du code général des impôts, est dénommée « fournisseur » la personne qui fabrique, importe ou acquiert dans un autre État membre des alcools et boissons alcooliques, ou qui détient ces produits après les avoir reçus ou achetés en vue de leur réexpédition ou de leur revente en l'état. Ce fournisseur doit :</p>
<p>1° Exercer son activité comme entrepositaire agréé dans les conditions prévues à l'article 302 G du code général des impôts ;</p>
<p>2° Recueillir et conserver le numéro d'identification communiqué par l'intermédiaire mentionné au 2° du II ou par l'utilisateur défini à l'article 111-0 F. La copie de leur déclaration préalable de profession n'est pas exigée ;</p>
<p>3° Identifier les personnes auxquelles il livre des alcools et boissons alcooliques dans ses documents commerciaux ou ses enregistrements de vente. Une extraction de ces données tient lieu de « liste clients » ; aucune liste séparée n'est exigée. À toute réquisition des agents des douanes et droits indirects, le fournisseur justifie par tout moyen ou document que les livraisons exonérées de droits d'accise ont été faites à une personne dûment autorisée ;</p>
<p>4° Expédier les alcools et boissons alcooliques sous couvert, selon le cas, du document d'accompagnement prévu à l'article 302 M du code général des impôts ou du document économique prévu aux a et c ci-dessous :</p>
<p>a. Pour les utilisateurs définis à l'article 111-0 F, le fournisseur établit le document d'accompagnement prévu au II de l'article 302 M du code général des impôts ou un document économique. Outre le numéro d'identification de l'utilisateur mentionné au 2° et les informations prescrites par le règlement (CEE) n° 3649/92 de la Commission du 17 décembre 1992, il porte :</p>
<p>Lorsqu'il utilise le formulaire type annexé à ce règlement, la mention : « Produits exonérés (art. 302 D bis du CGI) » ;</p>
<p>Lorsqu'il utilise à la place de ce formulaire le document commercial admis par ce règlement, les intitulés : « Communauté européenne » et « Document commercial simplifié d'accompagnement pour le contrôle fiscal des produits soumis à accises en régime d'exonération de droits » ;</p>
<p>b. Le document d'accompagnement prévu au I de l'article 302 M du code général des impôts et destiné à un intermédiaire mentionné au 2° du II porte le numéro d'identification de cet intermédiaire mentionné au 2° du présent I ;</p>
<p>c. Le document économique porte le numéro d'identification de l'utilisateur ou de l'intermédiaire mentionné au 2°, la mention « Produits exonérés (art. 302 D bis du CGI) » et la nature du produit justifiant l'exonération ;</p>
<p>d. Pour le transport des échantillons visés au e du II de l'article 302 D bis du code général des impôts au sein du territoire fiscal de la France métropolitaine et des départements d'outre-mer, aucun document d'accompagnement n'est exigé si leur situation régulière est justifiée par une marque spécifique portant l'indication « ECHANTILLON » sur les récipients ou sur les documents économiques qui les accompagnent ;</p>
<p>5° Conserver les documents et données prévus aux 2° à 4° ainsi que les pièces justificatives dans les conditions fixées à l'article L. 102 B du livre des procédures fiscales.</p>
<p>II. - Pour les préparations alimentaires à usage humain visées au d du II de l'article 302 D bis du code général des impôts, les obligations suivantes s'ajoutent à celles du I :</p>
<p>1° Le fournisseur qui fabrique, importe ou acquiert dans un autre État membre des alcools et boissons alcooliques appose sur les récipients une marque portant l'une des indications suivantes :</p>
<p>« Usage réservé aux professionnels pour les préparations alimentaires » ou « Destiné à la fabrication de denrées alimentaires et non à la vente au détail ».</p>
<p>Cette marque est indélébile, facilement lisible et visible dans les conditions habituelles de présentation. Elle est apposée de manière à empêcher son retrait ou sa réutilisation ;</p>
<p>2° Le fournisseur qui reçoit ou achète, pour les réexpédier ou les revendre en l'état, des alcools et boissons alcooliques dans des récipients portant la marque prévue au 1° est dénommé « intermédiaire ». Il déclare préalablement sa profession au service des douanes et droits indirects dont il dépend, en justifiant de son identité et de son activité, afin d'obtenir un numéro d'identification.</p>
<p>Tout refus d'attribution du numéro est motivé et notifié au déclarant.</p>
<p>L'intermédiaire communique son numéro d'identification au fournisseur défini au I. Il n'est pas tenu de lui remettre une copie de sa déclaration préalable de profession.</p>
<p>L'intermédiaire signale au service des douanes et droits indirects les changements de son activité par une mise à jour des seules informations modifiées. Il n'établit pas une nouvelle déclaration complète de profession pour ce seul motif.</p>
<p>Lorsqu'un nouveau numéro lui est attribué à la suite d'un changement d'activité, l'intermédiaire en informe son fournisseur en lui communiquant ce numéro, sans nouvelle copie de déclaration.</p>
<p>Les allègements documentaires prévus au présent article s'appliquent aux livraisons et aux changements d'activité intervenant à compter de l'entrée en vigueur de la présente réforme. Ils ne suppriment ni les conditions d'exonération ni les obligations de conservation des pièces relatives aux opérations antérieures.</p>
''',
    "Réforme de fond : suppression de la copie systématique de la déclaration professionnelle, de la liste clients séparée lorsque les ventes identifient déjà les destinataires et de la redéclaration complète pour une modification d'activité. Un numéro communiqué, des données commerciales réutilisables et une simple mise à jour remplacent ces doublons. À droit constant demeurent l'agrément du fournisseur, la preuve d'un destinataire autorisé, les documents de circulation, les marques alimentaires et d'échantillon ainsi que la conservation fiscale.",
    "Coordonner 111-0 F et les formulaires des intermédiaires : les renvois internes au 2° visent désormais le numéro, non une copie de déclaration. Préserver les mentions exactes des documents, les deux marques alimentaires et la condition de transport en France métropolitaine et DOM pour les échantillons. Le règlement (CEE) n° 3649/92 et l'article 302 M sont des références anciennes, ce dernier absent du fichier impots.json consulté : vérifier les textes européens et la recodification applicables avant harmonisation ; les obligations de circulation de droit de l'Union ne sont pas supprimées implicitement. Les informations nouvelles ne sont pas présumées publiques : organiser une vérification licite du statut du destinataire si nécessaire, sans reconstruire une collecte de déclarations en double.")

add('111-0 F', '''
<p>I. - Pour l'application du III de l'article 302 D bis du code général des impôts, est dénommé « utilisateur » l'opérateur qui entend bénéficier des exonérations des I et II de cet article ou qui fait commerce des alcools totalement dénaturés mentionnés au a de son I. Cet utilisateur doit :</p>
<p>1° Déclarer préalablement sa profession au service des douanes et droits indirects territorialement compétent, en justifiant de son identité et de son activité, afin d'obtenir un numéro d'identification ;</p>
<p>Tout refus d'attribution du numéro est motivé et notifié au déclarant.</p>
<p>L'utilisateur signale à ce service les changements de son activité par une mise à jour des seules informations modifiées. Il n'établit pas une nouvelle déclaration complète de profession pour ce seul motif ;</p>
<p>2° Communiquer son numéro d'identification au fournisseur ou à l'intermédiaire défini à l'article 111-0 E, selon le cas. La remise d'une copie de la déclaration préalable de profession n'est pas exigée ;</p>
<p>3° Conserver les documents d'accompagnement prévus au 4° du I de l'article 111-0 E et les pièces justificatives dans les conditions fixées à l'article L. 102 B du livre des procédures fiscales.</p>
<p>L'administration des douanes et droits indirects qui a délivré le numéro le retire lorsque son titulaire manque aux dispositions législatives ou réglementaires relatives aux exonérations de l'article 302 D bis du code général des impôts, ou lorsque son changement d'activité ne permet plus de bénéficier de l'exonération. La décision de retrait est motivée et notifiée à l'intéressé.</p>
<p>L'utilisateur informe ses fournisseurs du retrait de son numéro ou de l'attribution d'un nouveau numéro à la suite d'un changement d'activité. Dans ce dernier cas, il leur communique le nouveau numéro sans être tenu de transmettre une copie de sa déclaration de profession.</p>
<p>II. - La personne qui reçoit des alcools ou boissons alcooliques pour les utiliser aux fins et dans les cas prévus au b du I et au II de l'article 302 D bis du code général des impôts est soumise, outre le I du présent article, aux obligations suivantes :</p>
<p>1° Lorsqu'elle utilise ces produits dans les conditions prévues au b du I et aux a à d, h et i du II de l'article 302 D bis du code général des impôts, elle tient à la disposition du service, selon le cas, les documents décrivant la nature et la composition détaillée des produits fabriqués, les procédés et techniques de fabrication, l'estimation des taux moyens de déchets et le procédé de dénaturation utilisé. La production systématique de ce dossier à l'appui de la déclaration de profession n'est pas exigée. Les documents nécessaires à la vérification des conditions d'exonération sont communiqués sur demande du service. Cette règle ne dispense pas d'une autorisation du procédé de dénaturation lorsque celle-ci est requise par l'article 302 D bis ;</p>
<p>2° Elle justifie que les quantités reçues correspondent aux besoins réels et normaux de sa profession ou de son activité économique et qu'elles sont utilisées aux fins et dans les conditions prévues à l'article 302 D bis du code général des impôts. Elle peut utiliser tout moyen ou document, notamment des échantillons de produits fabriqués à partir d'alcools ou boissons alcooliques, des notices décrivant ces produits, la description des procédés et techniques de fabrication ou ses procédures et méthodes de contrôle interne de la qualité ;</p>
<p>3° Si elle est débitante de boissons, elle stocke les récipients portant la marque prévue au 1° du II de l'article 111-0 E séparément de ceux qu'elle reçoit pour son activité de débit de boissons.</p>
<p>Les mises à jour simplifiées et les dispenses de copies ou de production systématique de dossier s'appliquent aux formalités accomplies à compter de l'entrée en vigueur de la présente réforme. Elles ne régularisent pas les opérations antérieures et ne suppriment pas les obligations de conservation qui leur sont applicables.</p>
''',
    "Réforme de fond : suppression des copies de déclaration transmises aux fournisseurs, remplacement des redéclarations par une mise à jour et suppression du dépôt systématique du dossier technique déjà disponible chez l'utilisateur. Ce dossier demeure accessible au contrôle, et l'autorisation de dénaturation exigée par la loi reste distincte. Droit constant pour la déclaration initiale légale, les décisions motivées, les conditions d'emploi, la preuve des besoins et le stockage séparé chez les débitants.",
    "L'article 302 D bis III, lu dans le corpus, impose encore une déclaration préalable, électronique avec exception liée à l'absence de couverture internet : elle n'est pas supprimée. Coordonner les références croisées de 111-0 E, G et H et les formulaires ; conserver la distinction entre tous les utilisateurs du I et le sous-ensemble du II. Le dossier technique concerne précisément b du I et a à d, h et i du II, non tous les cas. Aucun retrait d'identification ni refus ne peut perdre sa motivation et sa notification par l'effet de la simplification. Vérifier la conformité des modalités de contrôle aux exonérations de la directive 92/83/CEE sans rétablir un envoi systématique.")

add('111-0 G', '''
<p>Dans les cas prévus au b du I et aux b à i du II de l'article 302 D bis du code général des impôts, les utilisateurs tiennent, en plus des obligations de l'article 111-0 F, une comptabilité matières des produits reçus et utilisés lorsqu'ils reçoivent annuellement au moins 100 litres d'alcools ou au moins 500 litres de boissons alcooliques. Ces seuils sont appréciés en volume effectif.</p>
<p>1° La comptabilité matières comprend les deux comptes suivants, qui peuvent être présentés par extraction d'un même système d'enregistrement :</p>
<p>a. Un compte principal des réceptions et des détentions d'alcools et de boissons alcooliques ;</p>
<p>b. Un compte de fabrication des produits.</p>
<p>2° Les quantités sont exprimées en volume d'alcool pur pour les alcools, en volume effectif pour les produits intermédiaires et les produits mentionnés à l'article 438 du code général des impôts, et en volume effectif par degré alcoométrique pour les bières.</p>
<p>La comptabilité matières comporte les renseignements suivants, sans qu'une double saisie soit exigée lorsque la même opération alimente les deux comptes :</p>
<p>a. Dans les « Entrées » du compte principal, les quantités d'alcools ou de boissons alcooliques reçues et détenues par l'utilisateur ;</p>
<p>b. Dans les « Sorties » du compte principal, les quantités d'alcools ou de boissons alcooliques destinées à être mises en œuvre ;</p>
<p>c. Dans les « Entrées » du compte de fabrication, pour chaque produit fabriqué, les quantités d'alcools et de boissons alcooliques mises en œuvre ;</p>
<p>d. Dans les « Sorties » du compte de fabrication, les quantités de produits fabriqués et leur teneur en alcool.</p>
<p>3° La comptabilité est tenue par exercice comptable, dans l'ordre chronologique des opérations, sur un support permettant sa conservation, sa restitution et son contrôle. Les registres de production, de stocks ou de gestion déjà tenus suffisent lorsqu'ils permettent de restituer les deux comptes et tous les renseignements prévus aux 1° et 2°. Aucun livre séparé ni copie de ces enregistrements n'est exigé. Les corrections laissent subsister l'inscription d'origine ainsi que la date et l'identification de leur auteur. Pour une tenue informatisée, les conditions de l'article 50-00 D de l'annexe IV au code général des impôts s'appliquent sous réserve des dispositions du présent 3° qui permettent la réutilisation des enregistrements et les corrections traçables.</p>
<p>Les opérations d'entrée ou de sortie prévues au 2° sont enregistrées au plus tard le jour ouvrable suivant leur réalisation.</p>
<p>4° La comptabilité matières et les pièces justificatives sont conservées dans les conditions fixées à l'article L. 102 B du livre des procédures fiscales et présentées à toute réquisition des agents des douanes et droits indirects.</p>
<p>La réutilisation des enregistrements et les modalités de tenue prévues au présent article s'appliquent à compter de l'entrée en vigueur de la présente réforme. Les données antérieures restent conservées et accessibles dans les conditions qui leur sont applicables.</p>
''',
    "Réforme de fond : suppression du registre autonome et de la double saisie lorsque la gestion existante fournit les comptes et les informations requis ; substitution de corrections traçables à l'interdiction matérielle de toute rature ou modification. Le contrôle conserve toutes les données, les deux comptes, les unités, les seuils et le délai du jour ouvrable suivant. La rédaction distingue les seuils en volume effectif des unités employées dans les comptes.",
    "Conserver 100 litres et 500 litres, seuils inclusifs par catégorie de produit, ainsi que b du I et b à i du II de 302 D bis. La source relie les seuils par « et » dans une phrase ambiguë ; la proposition les rend applicables chacun à sa catégorie, sans exiger un cumul d'alcools et de boissons alcooliques. À contrôler explicitement lors de la coordination. L'article 50-00 D de l'annexe IV, lu intégralement, impose notamment un compteur et l'impossibilité de modifier après validation : coordonner cette impossibilité avec les corrections traçables, sans étendre la réforme à tous les registres vitivinicoles. Les entrées de fabrication ne sont pas automatiquement identiques aux sorties destinées à être mises en œuvre : le rapprochement doit rester vérifiable et ne fusionne pas les faits de gestion.")

add('111-0 H', '''
<p>Pour l'exonération prévue au a du II de l'article 302 D bis du code général des impôts, les utilisateurs qui produisent du vinaigre sont soumis, outre l'article 111-0 F, aux obligations suivantes :</p>
<p>1° Tenir une comptabilité matières des alcools et boissons alcooliques reçus et mis en œuvre. Elle comprend un compte principal retraçant les réceptions et les détentions de produits ainsi que les produits issus de leur transformation en dilutions acéto-alcooliques.</p>
<p>Ce compte distingue les « Entrées » et les « Sorties » :</p>
<p>a. Les « Entrées » indiquent les quantités de produits ou d'autres matières premières reçues et détenues ainsi que leur richesse alcoolique effective ;</p>
<p>b. Les « Sorties » indiquent les quantités de produits mises en œuvre pour fabriquer du vinaigre ;</p>
<p>2° Pour les fabricants qui reçoivent et utilisent des produits vitivinicoles régis par le règlement (CE) n° 1493/1999 du Conseil du 17 mai 1999 portant organisation commune du marché vitivinicole, tenir à la disposition du service des douanes et droits indirects territorialement compétent les données pouvant être extraites de leur comptabilité matières. Ces données sont communiquées à la demande du service. Au titre du présent article, aucune déclaration récapitulative mensuelle distincte ni transmission au plus tard le dixième jour du mois n'est exigée. Cette suppression ne dispense pas d'une déclaration directement exigée par le droit de l'Union européenne. Les données concernées sont les suivantes :</p>
<p>a. Les quantités de produits vitivinicoles mises en œuvre pour fabriquer du vinaigre au cours de chaque mois ;</p>
<p>b. Le total des quantités mises en œuvre depuis le début de la campagne, à l'exclusion de celles du mois considéré au a ;</p>
<p>c. Le total des quantités prévues aux a et b.</p>
<p>3° La comptabilité est tenue par exercice comptable, dans l'ordre chronologique des opérations, sur un support permettant sa conservation, sa restitution et son contrôle. Les registres de production, de stocks ou de gestion déjà tenus suffisent s'ils restituent tous les renseignements du 1°. Aucun livre séparé ni copie de ces enregistrements n'est exigé. Les corrections laissent subsister l'inscription d'origine ainsi que la date et l'identification de leur auteur. Pour une tenue informatisée, les conditions de l'article 50-00 D de l'annexe IV au code général des impôts s'appliquent sous réserve du présent 3°, qui permet la réutilisation des enregistrements et les corrections traçables.</p>
<p>Les opérations d'entrée ou de sortie prévues au 1° sont enregistrées au plus tard le jour ouvrable suivant leur réalisation.</p>
<p>La suppression de la transmission mensuelle s'applique aux mois commençant à compter de l'entrée en vigueur de la présente réforme. Les déclarations relatives aux mois antérieurs restent dues selon les règles antérieures. Les modalités simplifiées de tenue des comptes s'appliquent à compter de cette entrée en vigueur, sans suppression des données antérieures ni de leurs obligations de conservation.</p>
''',
    "Réforme de fond : suppression de la déclaration mensuelle autonome de fabrication de vinaigre, les mêmes données étant déjà disponibles dans la comptabilité matières et restant communicables au contrôle. Les trois calculs a à c sont maintenus. Le livre séparé et l'interdiction de correction sont remplacés par la réutilisation de registres existants et la traçabilité des corrections. Les opérations et la richesse alcoolique demeurent enregistrées au plus tard le jour ouvrable suivant ; aucune obligation européenne directement applicable n'est effacée.",
    "Coordonner les formulaires douaniers de fabrication de vinaigre, 111-0 F, 302 D bis II a et 50-00 D de l'annexe IV. La référence source au règlement (CE) n° 1493/1999 est ancienne ; vérifier son articulation avec le règlement (UE) n° 1308/2013 et les règlements délégué (UE) 2018/273 et d'exécution (UE) 2018/274 pour identifier les éventuelles déclarations ou registres européens subsistants. Ces textes ne sont pas consultables dans le corpus fourni : aucune conclusion de disparition de toute déclaration européenne n'est posée. Le délai national du dixième jour est expressément supprimé pour les nouveaux mois, sans remise des déclarations antérieures. La suppression figure dans le 2° ; les a à c et le 3° restent à leur place.")

add('111-0 HA', '''
<p>Les voyageurs ne peuvent réintroduire des alcools, boissons alcooliques et tabacs manufacturés sur le territoire de l'Union européenne que dans les limites et selon les conditions applicables à ces produits.</p>
<p>Lors de l'importation, ils déclarent ces produits à l'administration des douanes et droits indirects. Ils acquittent les droits d'accise sur les quantités qui dépassent les limites applicables.</p>
''',
    "Réécriture à droit constant : le voyageur est désigné comme responsable de la déclaration et le paiement est rattaché à la seule fraction excédentaire. Les limites de réintroduction et les contrôles sont maintenus, car ils relèvent de régimes douaniers et d'accises coordonnés au niveau européen ; aucune déclaration en double propre à cet article n'est identifiée.",
    "La source ne chiffre aucune franchise : ne pas importer les niveaux commerciaux de 111-0 A dans ce régime de voyageurs. Vérifier l'articulation avec les franchises européennes à l'importation, notamment la directive 2007/74/CE, et les règles douanières de déclaration. La proposition ne crée ni plafond absolu nouveau ni taxation de la fraction couverte par une franchise. Les limites et conditions extérieures à l'article restent à contrôler dans leurs textes propres.")

add('111-0 HB', '''
<p>I. - Les voyageurs se rendant par voie aérienne ou maritime dans un autre État membre de l'Union européenne peuvent acheter dans les comptoirs de vente des alcools, boissons alcooliques et tabacs manufacturés en droits acquittés.</p>
<p>Pour ces achats en droits acquittés, la présentation d'un titre de transport indiquant la destination finale n'est pas exigée au titre du présent article.</p>
<p>II. - Les membres de l'équipage d'un aéronef ou d'un navire peuvent acheter dans les comptoirs de vente des produits exonérés de droits d'accise s'ils présentent, lors de l'achat, un ordre de mission attestant que leur destination se situe hors du territoire de l'Union européenne. Lorsque leur moyen de transport a pour destination un État membre de l'Union européenne, leurs achats de produits soumis à accise sont effectués en droits acquittés.</p>
<p>III. - Lors de la vente, l'entrepositaire agréé établit un document commercial et en remet un exemplaire à l'acheteur. Le document indique notamment la nature et le volume des produits ainsi que leur statut fiscal, en précisant si les droits d'accise sont acquittés. Pour une vente exonérée, il indique également l'identité de l'acheteur et sa destination finale. Ces deux dernières informations ne sont pas exigées au titre du présent article pour une vente en droits acquittés.</p>
<p>Un arrêté du ministre chargé du budget précise les informations du document commercial dans les limites prévues au III ; il ne peut imposer l'identité et la destination finale pour les ventes en droits acquittés sur le fondement du présent article.</p>
<p>Le document commercial est conservé dans les conditions fixées à l'article L. 102 B du livre des procédures fiscales.</p>
<p>La dispense de présentation du titre de transport et de collecte de l'identité et de la destination pour les ventes en droits acquittés s'applique aux achats effectués à compter de l'entrée en vigueur de la présente réforme. La conservation des pièces relatives aux ventes antérieures demeure régie par les règles applicables à ces ventes.</p>
''',
    "Réforme de fond : suppression de la présentation du titre de transport pour un achat déjà taxé et de la collecte systématique de l'identité et de la destination finale sur les ventes en droits acquittés. La justification de la destination hors Union pour les achats exonérés des équipages, les informations fiscales du reçu et sa conservation restent exigées. Les numéros I à III sont maintenus.",
    "Modifier l'arrêté pris pour le document commercial afin qu'il ne réintroduise pas les données supprimées. La dispense ne concerne que les exigences fiscales du présent article : les vérifications d'accès aéroportuaire, de sûreté et d'âge de vente, lorsqu'elles ont un autre fondement, ne sont pas abrogées. Les ventes exonérées restent nominatives et soumises à la preuve de destination ; ne pas étendre les franchises aux trajets intracommunautaires. Vérifier la coordination des comptoirs avec les règles européennes de vente hors taxes, notamment la directive (UE) 2020/262, et avec 111-0 HC/HD.")

add('111-0 HC', '''
<p>Les voyageurs à destination d'un État membre de l'Union européenne peuvent acheter des alcools, boissons alcooliques et tabacs manufacturés en droits acquittés dans les boutiques de vente à bord.</p>
<p>Les ventes à bord exonérées de droits d'accise ne peuvent être effectuées que pendant la navigation.</p>
<p>Lors de chaque vente à bord, le responsable de la boutique établit un document commercial et en remet un exemplaire à l'acheteur. Ce document indique la nature et le volume des produits vendus ainsi que leur statut fiscal.</p>
<p>Un arrêté du ministre chargé du budget précise les informations du document commercial, dans le respect de la dispense prévue à l'alinéa suivant.</p>
<p>Pour toute vente en droits acquittés, le document commercial n'a pas à indiquer le nom du voyageur ni la destination figurant sur son titre de transport. Pour les produits vendus en droits acquittés à bord d'un navire n'effectuant que des navigations intracommunautaires, il indique la liaison maritime concernée.</p>
<p>Le document commercial est conservé dans les conditions fixées à l'article L. 102 B du livre des procédures fiscales.</p>
<p>La dispense de mention du nom et de la destination s'applique aux ventes en droits acquittés effectuées à compter de l'entrée en vigueur de la présente réforme. Les règles de conservation des pièces relatives aux ventes antérieures demeurent applicables.</p>
''',
    "Réforme de fond : la dispense de données nominatives et de destination est étendue à toutes les ventes à bord en droits acquittés, au lieu de la seule faculté prévue pour certains navires. Les ventes exonérées ne bénéficient pas de cette extension. Droit constant pour la navigation, les mentions de produits et de statut fiscal, le reçu remis au client, la liaison des navires exclusivement intracommunautaires et la conservation.",
    "Coordonner l'arrêté ministériel et 111-0 HB. L'alinéa 5 reste à sa place ; il conserve l'indication de liaison maritime pour les navires n'effectuant que des navigations intracommunautaires et n'impose pas une nouvelle collecte équivalente aux autres ventes. La condition « pendant la navigation » ne remplace pas les autres conditions légales et européennes d'exonération, notamment le trajet ouvrant droit aux ventes hors taxes. Vérifier le régime applicable aux aéronefs sans déduire du seul présent article une extension des exonérations.")

add('111-0 HD', '''
<p>Pour l'application du 3° de l'article 302 F bis du code général des impôts, constitue une navigation maritime soit une navigation effectuée hors des eaux intérieures au sens de la Convention des Nations unies sur le droit de la mer et durant au moins six heures, soit une navigation comportant une sortie des eaux territoriales.</p>
<p>Lorsque la consommation de tabacs est interdite à bord d'un aéronef, les tabacs manufacturés ne bénéficient pas à son bord de l'exonération de droits d'accise prévue au 3° de l'article 302 F bis du code général des impôts.</p>
''',
    "Réécriture à droit constant : les deux branches alternatives définissant la navigation maritime sont distinguées, sans appliquer le délai de six heures à la sortie des eaux territoriales. L'exclusion des tabacs dont la consommation à bord est interdite est conservée pour éviter une exonération sans usage autorisé. Cet article ne porte pas de formalité en double à supprimer.",
    "Le 3° de l'article 302 F bis n'est pas présent dans le fichier impots.json du corpus fourni : référence préexistante à coordonner avec la recodification des accises avant adoption, sans inventer un nouvel article. Conserver la Convention des Nations unies sur le droit de la mer, la distinction eaux intérieures/eaux territoriales et la durée inclusive de six heures pour la seule première branche. Le second alinéa concerne les tabacs et la consommation à bord des aéronefs, non toute vente de tabac aux voyageurs. Vérifier le champ des exonérations européennes d'avitaillement et les régimes nationaux correspondants.")

assert len(sources) == 24
assert len(drafts) == 24
answer = []
for source in sources:
    item = {key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    item.update(drafts[source['number']])
    answer.append(item)
Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
print(f'{len(answer)} articles écrits dans answer.json')
